#!/bin/sh
# agenteval opencode worker -- generated by agenteval, do not edit.
# Runs one OpenCode task for the orchestrating agent. Requests go to the
# orchestrator's Inspect model bridge (ANTHROPIC_BASE_URL) under the model name
# @@WORKER_MODEL@@, which the bridge routes to the subagent model on the host.
# It already runs inside the orchestrator's inner sandbox, so it starts the
# OpenCode binary directly (nested bubblewrap is not possible).
set -eu
if [ "$#" -lt 1 ]; then
    echo 'usage: opencode-worker "<task instructions>"' >&2
    exit 2
fi
sx_base=${ANTHROPIC_BASE_URL:-}
case "$sx_base" in
    http://localhost:[0-9]*|http://127.0.0.1:[0-9]*) ;;
    *)
        echo "opencode-worker: ANTHROPIC_BASE_URL is not the local model bridge" >&2
        exit 2
        ;;
esac
sx_base=${sx_base%/}
sx_base=${sx_base%/v1}
sx_cfg="$HOME/.config/opencode/agenteval-worker.json"
mkdir -p "$HOME/.config/opencode"
printf '{"$schema":"https://opencode.ai/config.json","provider":{"openrouter":{"options":{"baseURL":"%s/v1"},"models":{"@@WORKER_MODEL@@":{"name":"agenteval worker"}}}}}\n' \
    "$sx_base" >"$sx_cfg"
OPENCODE_CONFIG=$sx_cfg
OPENROUTER_API_KEY=sk-none
OPENCODE_DISABLE_AUTOUPDATE=1
OPENCODE_DISABLE_MODELS_FETCH=1
OPENCODE_DISABLE_DEFAULT_PLUGINS=1
npm_config_offline=true
PATH=@@DEP_PATH@@:$PATH
export OPENCODE_CONFIG OPENROUTER_API_KEY OPENCODE_DISABLE_AUTOUPDATE \
    OPENCODE_DISABLE_MODELS_FETCH OPENCODE_DISABLE_DEFAULT_PLUGINS npm_config_offline PATH
# The Inspect bridge serialises the worker model's reasoning into its chat-completions
# text as <think signature="...">...</think>, which OpenCode then prints. A real
# provider would not, so strip those blocks before the orchestrator reads the output.
sx_strip='{
    line = $0; out = ""; hit = skip
    while (line != "") {
        if (skip) {
            i = index(line, "</think>")
            if (i == 0) { line = "" } else { line = substr(line, i + 8); skip = 0 }
        } else {
            i = index(line, "<think")
            if (i == 0) { out = out line; line = "" }
            else { out = out substr(line, 1, i - 1); line = substr(line, i); skip = 1; hit = 1 }
        }
    }
    if (!hit || out ~ /[^[:space:]]/) print out
}'
sx_dir=$(mktemp -d "${TMPDIR:-/tmp}/opencode-worker.XXXXXX")
trap 'rm -rf "$sx_dir"' EXIT
# Seconds OpenCode may stay silent before its first output; it is then stopped so the
# orchestrator gets an error instead of a worker that never finishes.
sx_quiet=${AGENTEVAL_WORKER_QUIET_LIMIT:-180}
set +e
{
    # `opencode run` reads all of a non-terminal stdin into the prompt, so an inherited
    # pipe that never closes would hang it before its first request.
    @@BINARY@@ run --model openrouter/@@WORKER_MODEL@@ --title=agenteval-worker \
        --dangerously-skip-permissions "$*" </dev/null 2>&1 &
    echo $! >"$sx_dir/pid"
    wait $!
    echo $? >"$sx_dir/status"
} | awk -v mark="$sx_dir/started" 'NR == 1 { printf "" > mark; close(mark) }'"$sx_strip" &
sx_filter=$!
sx_waited=0
while [ ! -e "$sx_dir/started" ] && kill -0 "$sx_filter" 2>/dev/null; do
    if [ "$sx_waited" -ge "$sx_quiet" ]; then
        kill "$(cat "$sx_dir/pid")" "$sx_filter" 2>/dev/null
        echo "opencode-worker: OpenCode printed nothing for ${sx_quiet}s and was stopped; run the worker again" >&2
        exit 124
    fi
    sleep 1
    sx_waited=$((sx_waited + 1))
done
wait "$sx_filter"
exit "$(cat "$sx_dir/status" 2>/dev/null || echo 1)"
